mod tests {
    use super::*;

    #[test]
    fn str_and_string() {
        assert!(Container::contains("hello world", "world"));
        assert!(!Container::contains("hello world", "nope"));

        let owned = String::from("hello world");
        assert!(Container::contains(&owned, "hello"));
        assert!(!Container::contains(&owned, "bye"));
    }

    #[test]
    fn arrays_slices_vecs() {
        let arr = [1, 2, 3];
        assert!(Container::contains(&arr, &2));
        assert!(!Container::contains(&arr, &9));

        let slice: &[i32] = &arr;
        assert!(Container::contains(&slice, &3));

        let v = vec![1, 2, 3];
        assert!(Container::contains(&v, &1));
        assert!(!Container::contains(&v, &4));
    }

    #[test]
    fn sets_and_maps() {
        let set: HashSet<i32> = [1, 2, 3].into_iter().collect();
        assert!(Container::contains(&set, &2));

        let bset: BTreeSet<i32> = [1, 2, 3].into_iter().collect();
        assert!(Container::contains(&bset, &3));

        let map: HashMap<&str, i32> = [("a", 1)].into_iter().collect();
        assert!(Container::contains(&map, &"a"));
        assert!(!Container::contains(&map, &"b"));

        let bmap: BTreeMap<&str, i32> = [("a", 1)].into_iter().collect();
        assert!(Container::contains(&bmap, &"a"));
    }

    #[test]
    fn ranges() {
        assert!(Container::contains(&(0..10), &5));
        assert!(!Container::contains(&(0..10), &10));
        assert!(Container::contains(&(0..=10), &10));
        assert!(Container::contains(&(5..), &100));
        assert!(Container::contains(&(..10), &1));
        assert!(Container::contains(&(..=10), &10));
    }
}
